from typing import List

class PromptBuilder:

    @staticmethod
    def build_prompt(preferences: List[str]) -> str:
        base_prompt_start = """Проаналізуй склад харчового продукту з наданих фотографій упаковки (може бути від 1 до 4 фото). Кілька фото можуть бути надані через форму упаковки або тому, що назва і склад розміщені на різних боках, тощо.
Якщо на фото зображено не харчовий продукт для людей (наприклад, корм для тварин, косметика, побутова хімія, ліки, тощо), то поверни JSON з полем "error": "Це не харчовий продукт для людей" і більше нічого. Якщо склад продукту на фото неможливо прочитати взагалі, то поверни JSON з полем "error": "Склад не вдалося прочитати" і більше нічого.
Аналіз надавай виключно українською мовою, навіть якщо текст на етикетці іншою мовою. Якщо якийсь текст на фото нечіткий або частково прихований, то аналізуй лише те, що вдалося прочитати, не вигадуй інгредієнтів, яких не бачиш. Аналізуй лише склад (інгредієнти). Зберігай оригінальний порядок інгредієнтів, як на упаковці. Виділяй усі інгредієнти без винятку."""

        if preferences and len(preferences) > 0:
            user_checks = ", ".join(preferences)
            preferences_block = f"""
Користувач вказав, що додатково хоче перевірити цей продукт на (або в нього запитання якесь) : {user_checks}. Якщо цей запит стосуються харчування, складу, алергенів, протипоказань або впливу продукту на здоров'я, тобто чогось по темі аналізу складу продукту харчування, то дай зрозумілу, простими словами написану відповідь у полі "user_note" . І обгрунтовуй свою відповідь посилаючись на інгредієнти зі складу. Якщо запит не стосуються аналізу харчового продукту або є беззмістовними, то напиши у полі "user_note": "Не вдалось перевірити продукт на додатковий запит, бо він виходить за межі аналізу харчових продуктів". Якщо запит частково релевантний, наприклад "глютен, лактоза, 1+1", то відповідь надавай тільки на коректні питання, які стосуються тематики."""
            json_structure = """
Результат надай строго у форматі JSON, без будь-якого додаткового тексту до або після, за такою структурою:
{
"product_name": "Назва продукту з фото (як на упаковці). Якщо назву не видно, то залиши порожній рядок, сам не вигадуй",
"translated_product_name": "Переклад назви продукту українською. Якщо продукт український, то залиши порожній рядок",
"user_note": "Відповідь на додаткові запити користувача щодо продукту. Присутнє це поле лише якщо користувач вказав додаткові запити.",
"ingredients": [
{
"name": "Назва інгредієнта (як на упаковці)",
"translated_name": "Переклад назви інгредієнта українською. Якщо продукт український, то залиши порожній рядок",
"description": "Поясни що це таке, звідки береться, для чого додається до продукту, яку функцію виконує. Пиши просто і зрозуміло, як для людини без медичної освіти, якщо викоритовуєшь якісь терміни, пиши їх пояснення.",
"benefits": "Користь для здоров'я. Коротко вкажи ключові поживні властивості або корисні речовини, наприклад “клітковина, залізо, вітамін С”. Не пояснюй механізм впливу на організм цих корисних елементів, просто переліч їх. Якщо реальної користі немає, то написати: 'Для здоров'я користі не має'",
"harm": "Шкода для здоров'я. Коротко напиши шкідливі для здоров’я речовини або властивості цього інгредієнту, наприклад “кофеїн, глютен, висококалорійний”. Не пояснюй механізм впливу цих шкідливих компонентів на організм, не вказуй тут хвороби які ці компоненти можуть викликати, просто переліч. Якщо шкода не виявлена при помірному вживанні, то написати: 'При помірному вживанні шкоди не виявлено'"
}
]
}"""
        else:
            preferences_block = ""
            json_structure = """
Результат надай строго у форматі JSON, без будь-якого додаткового тексту до або після, за такою структурою:
{
"product_name": "Назва продукту з фото (як на упаковці). Якщо назву не видно, то залиши порожній рядок, сам не вигадуй",
"translated_product_name": "Переклад назви продукту українською. Якщо продукт український, то залиши порожній рядок",
"ingredients": [
{
"name": "Назва інгредієнта (як на упаковці)",
"translated_name": "Переклад назви інгредієнта українською. Якщо продукт український, то залиши порожній рядок",
"description": "Поясни що це таке, звідки береться, для чого додається до продукту, яку функцію виконує. Пиши просто і зрозуміло, як для людини без медичної освіти, якщо викоритовуєшь якісь терміни, пиши їх пояснення.",
"benefits": "Користь для здоров'я. Коротко вкажи ключові поживні властивості або корисні речовини, наприклад “клітковина, залізо, вітамін С”. Не пояснюй механізм впливу на організм цих корисних елементів, просто переліч їх. Якщо реальної користі немає, то написати: 'Для здоров'я користі не має'",
"harm": "Шкода для здоров'я. Коротко напиши шкідливі для здоров’я речовини або властивості цього інгредієнту, наприклад “кофеїн, глютен, висококалорійний”. Не пояснюй механізм впливу цих шкідливих компонентів на організм, не вказуй тут хвороби які ці компоненти можуть викликати, просто переліч. Якщо шкода не виявлена при помірному вживанні, то написати: 'При помірному вживанні шкоди не виявлено'"
}
]
}"""

        return f"{base_prompt_start}\n{preferences_block}\n{json_structure}"